@IsTest
private class OwnerFormulaObservation {
    private static Map<String,Object> observe(String caseId, String expectedOwnerId) {
        Map<String,Object> row = new Map<String,Object>{'stage'=>'createInterview', 'setupError'=>false};
        try {
            Flow.Interview interview = Flow.Interview.createInterview('OwnedOwnerFormula', new Map<String,Object>{'caseId'=>caseId});
            row.put('stage', 'start');
            interview.start();
            row.put('stage', 'readOutputs');
            Object typedOwner = interview.getVariableValue('typedOwnerId');
            Object formulaActor = interview.getVariableValue('formulaActorId');
            Object actor = interview.getVariableValue('actorId');
            Object ordinaryOwner = interview.getVariableValue('ordinaryOwnerId');
            Object literalValue = interview.getVariableValue('literalValue');
            Object selected = interview.getVariableValue('selectedIds');
            row.put('typedOwnerIsNull',typedOwner==null);
            row.put('typedOwnerMatchesExpected',(String)typedOwner==expectedOwnerId);
            row.put('typedOwnerIsCurrentUser',(String)typedOwner==UserInfo.getUserId());
            row.put('formulaActorIsCurrentUser',(String)formulaActor==UserInfo.getUserId());
            row.put('actorLength',actor==null?null:((String)actor).length());
            row.put('currentUserLength',UserInfo.getUserId().length());
            row.put('actorIdMatches',actor!=null && (Id)(String)actor==(Id)UserInfo.getUserId());
            row.put('formulaActorIdMatches',formulaActor!=null && (Id)(String)formulaActor==(Id)UserInfo.getUserId());
            row.put('actorIsNull', actor == null);
            row.put('actorIsCurrentUser', actor != null && (String)actor == UserInfo.getUserId());
            row.put('ordinaryOwnerIsNull', ordinaryOwner == null);
            row.put('ordinaryOwnerMatchesExpected', (String)ordinaryOwner == expectedOwnerId);
            row.put('literalMatches', (String)literalValue == 'owned');
            row.put('selectedIsNull', selected == null);
            if (selected != null) {
                List<String> values = (List<String>)selected;
                row.put('firstSelectedLength',values.isEmpty()?null:values[0].length());
                row.put('firstSelectedIdMatches',!values.isEmpty() && (Id)values[0]==(Id)UserInfo.getUserId());
                row.put('selectedSize', values.size());
                row.put('containsCurrentUser', values.contains(UserInfo.getUserId()));
                row.put('containsExpectedOwner', values.contains(expectedOwnerId));
                row.put('containsNull', values.contains(null));
            }
            row.put('stage', 'complete');
        } catch (Exception issue) {
            row.put('exceptionType', issue.getTypeName());
            row.put('exceptionMessage', issue.getMessage());
        }
        return row;
    }

    private static void emit(String cell, Map<String,Object> row) {
        row.put('cell', cell);
        row.put('sourceApi', '65.0');
        row.put('callerApi', '65.0');
        System.assertEquals('capture', 'FLOW_OWNER_OBSERVATION ' + JSON.serialize(row));
    }

    @IsTest static void userOwnedCase() {
        Map<String,Object> row = new Map<String,Object>{'stage'=>'setupCase', 'setupError'=>true};
        try {
            Case record = new Case(Subject='Owned formula input', Origin='Phone', Status='New', OwnerId=UserInfo.getUserId());
            insert record;
            row = observe(record.Id, record.OwnerId);
        } catch (Exception issue) {
            row.put('exceptionType', issue.getTypeName());
            row.put('exceptionMessage', issue.getMessage());
        }
        emit('userOwnedCase', row);
    }

    @IsTest static void missingLookup() {
        emit('missingLookup', observe('500000000000071', null));
    }

    @IsTest static void queueOwnedCase() {
        Map<String,Object> row = new Map<String,Object>{'stage'=>'setupQueue', 'setupError'=>true};
        try {
            Case record;
            System.runAs(new User(Id=UserInfo.getUserId())) {
